package main

import (
	"context"
	"fmt"
	"net"
	"os"
	"strings"
	"time"

	"github.com/sirupsen/logrus"
	"google.golang.org/grpc"
	podresourcesapi "k8s.io/kubelet/pkg/apis/podresources/v1alpha1"
)

var (
	socketDir  = "/var/lib/kubelet/pod-resources"
	socketPath = socketDir + "/kubelet.sock"

	connectionTimeout = 10 * time.Second
)

func NewPodMapper(c *Config) *PodMapper {
	logrus.Infof("Kubernetes metrics collection enabled!")

	return &PodMapper{
		Config: c,
	}
}

func (p *PodMapper) Name() string {
	return "podMapper"
}

func (p *PodMapper) Process(metrics [][]Metric, sysInfo SystemInfo) error {
	_, err := os.Stat(socketPath)
	if os.IsNotExist(err) {
		logrus.Infof("No Kubelet socket, ignoring")
		return nil
	}

	// TODO: This needs to be moved out of the critical path.
	c, cleanup, err := connectToServer(socketPath)
	if err != nil {
		return err
	}
	defer cleanup()

	pods, err := ListPods(c)
	if err != nil {
		return err
	}

	deviceToPod := ToDeviceToPod(pods, sysInfo)

	// Note: for loop are copies the value, if we want to change the value
	// and not the copy, we need to use the indexes
	for i, device := range metrics {
		for j, val := range device {
			deviceId, err := val.getIDOfType(p.Config.KubernetesGPUIdType)
			if err != nil {
				return err
			}
			if !p.Config.UseOldNamespace {
				metrics[i][j].Attributes[podAttribute] = deviceToPod[deviceId].Name
				metrics[i][j].Attributes[namespaceAttribute] = deviceToPod[deviceId].Namespace
				metrics[i][j].Attributes[containerAttribute] = deviceToPod[deviceId].Container
			} else {
				metrics[i][j].Attributes[oldPodAttribute] = deviceToPod[deviceId].Name
				metrics[i][j].Attributes[oldNamespaceAttribute] = deviceToPod[deviceId].Namespace
				metrics[i][j].Attributes[oldContainerAttribute] = deviceToPod[deviceId].Container
			}
		}
	}

	return nil
}

func connectToServer(socket string) (*grpc.ClientConn, func(), error) {
	ctx, cancel := context.WithTimeout(context.Background(), connectionTimeout)
	defer cancel()

	conn, err := grpc.DialContext(ctx, socket, grpc.WithInsecure(), grpc.WithBlock(),
		grpc.WithDialer(func(addr string, timeout time.Duration) (net.Conn, error) {
			return net.DialTimeout("unix", addr, timeout)
		}),
	)

	if err != nil {
		return nil, func() {}, fmt.Errorf("failure connecting to %s: %v", socket, err)
	}

	return conn, func() { conn.Close() }, nil
}

func ListPods(conn *grpc.ClientConn) (*podresourcesapi.ListPodResourcesResponse, error) {
	client := podresourcesapi.NewPodResourcesListerClient(conn)

	ctx, cancel := context.WithTimeout(context.Background(), connectionTimeout)
	defer cancel()

	resp, err := client.List(ctx, &podresourcesapi.ListPodResourcesRequest{})
	if err != nil {
		return nil, fmt.Errorf("failure getting pod resources %v", err)
	}

	return resp, nil
}

func ToDeviceToPod(devicePods *podresourcesapi.ListPodResourcesResponse, sysInfo SystemInfo) map[string]PodInfo {
	deviceToPodMap := make(map[string]PodInfo)

	for _, pod := range devicePods.GetPodResources() {
		for _, container := range pod.GetContainers() {
			for _, device := range container.GetDevices() {

				resourceName := device.GetResourceName()
				if resourceName != nvidiaResourceName {
					// Mig resources appear differently than GPU resources
					if strings.HasPrefix(resourceName, nvidiaMigResourcePrefix) == false {
						continue
					}
				}

				podInfo := PodInfo{
					Name:      pod.GetName(),
					Namespace: pod.GetNamespace(),
					Container: container.GetName(),
				}

				for _, uuid := range device.GetDeviceIds() {
					if strings.HasPrefix(uuid, MIG_UUID_PREFIX) {
						// MIG uuid for now at least is in the format MIG-GPU-<gpu uuid>/<gpu instance index>/<compute instance index>
						// Remove the prefix and suffix to get the GPU's uuid
						gpuUuid := uuid[len(MIG_UUID_PREFIX):]
						index := strings.Index(gpuUuid, "/")
						if index > -1 {
							gIIdStr := gpuUuid[index+1:]
							index2 := strings.Index(gIIdStr, "/")
							gIIdStr = gIIdStr[0:index2]
							gpuUuid = gpuUuid[0:index]

							giIdentifier := GetGpuInstanceIdentifier(sysInfo, gpuUuid, gIIdStr)
							deviceToPodMap[giIdentifier] = podInfo
						}
						deviceToPodMap[gpuUuid] = podInfo
					} else {
						deviceToPodMap[uuid] = podInfo
					}
				}
			}
		}
	}

	return deviceToPodMap
}

package dcgm

import (
	"fmt"
	"os"
	"sync"
)

var (
	dcgmInitCounter int
	mux             sync.Mutex
)

// Init starts DCGM, based on the user selected mode
// DCGM can be started in 3 differengt modes:
// 1. Embedded: Start hostengine within this process
// 2. Standalone: Connect to an already running nv-hostengine at the specified address
// Connection address can be passed as command line args: -connect "IP:PORT/Socket" -socket "isSocket"
// 3. StartHostengine: Open an Unix socket to start and connect to the nv-hostengine and terminate before exiting
func Init(m mode, args ...string) (cleanup func(), err error) {
	mux.Lock()
	if dcgmInitCounter < 0 {
		count := fmt.Sprintf("%d", dcgmInitCounter)
		err = fmt.Errorf("Shutdown() is called %s times, before Init()", count[1:])
	}
	if dcgmInitCounter == 0 {
		err = initDcgm(m, args...)
	}
	dcgmInitCounter += 1
	mux.Unlock()

	return func() {
		if err := Shutdown(); err != nil {
			fmt.Fprintf(os.Stderr, "Failed to shutdown DCGM with error: `%v`", err)
		}
	}, err
}

// Shutdown stops DCGM and destroy all connections
func Shutdown() (err error) {
	mux.Lock()
	if dcgmInitCounter <= 0 {
		err = fmt.Errorf("Init() needs to be called before Shutdown()")
	}
	if dcgmInitCounter == 1 {
		err = shutdown()
	}
	dcgmInitCounter -= 1
	mux.Unlock()

	return
}

// GetAllDeviceCount counts all GPUs on the system
func GetAllDeviceCount() (uint, error) {
	return getAllDeviceCount()
}

// GetSupportedDevices returns only DCGM supported GPUs
func GetSupportedDevices() ([]uint, error) {
	return getSupportedDevices()
}

// GetDeviceInfo describes the given device
func GetDeviceInfo(gpuId uint) (Device, error) {
	return getDeviceInfo(gpuId)
}

// GetDeviceStatus monitors GPU status including its power, memory and GPU utilization
func GetDeviceStatus(gpuId uint) (DeviceStatus, error) {
	return latestValuesForDevice(gpuId)
}

// GetDeviceTopology returns device topology corresponding to the gpuId
func GetDeviceTopology(gpuId uint) ([]P2PLink, error) {
	return getDeviceTopology(gpuId)
}

// WatchPidFields lets DCGM start recording stats for GPU process
// It needs to be called before calling GetProcessInfo
func WatchPidFields() (GroupHandle, error) {
	return watchPidFields()
}

// GetProcessInfo provides detailed per GPU stats for this process
func GetProcessInfo(group GroupHandle, pid uint) ([]ProcessInfo, error) {
	return getProcessInfo(group, pid)
}

// HealthCheckByGpuId monitors GPU health for any errors/failures/warnings
func HealthCheckByGpuId(gpuId uint) (DeviceHealth, error) {
	return healthCheckByGpuId(gpuId)
}

// Policy sets GPU usage and error policies and notifies in case of any violations via callback functions
func Policy(gpuId uint, typ ...policyCondition) (<-chan PolicyViolation, error) {
	return registerPolicy(gpuId, typ...)
}

// Introspect returns DCGM hostengine memory and CPU usage
func Introspect() (DcgmStatus, error) {
	return introspect()
}

// Get all of the profiling metric groups for a given GPU group.
func GetSupportedMetricGroups(grpid uint) ([]MetricGroup, error) {
	return getSupportedMetricGroups(grpid)
}

