	h := getHealth(resp, req)
	if h == nil {
		return
	}
	if isJson(req) {
		encode(resp, req, h)
		return
	}
	print(resp, req, h, healthStatus)
}

func DcgmStatus(resp http.ResponseWriter, req *http.Request) {
	st := getDcgmStatus(resp, req)
	if st == nil {
		return
	}
	if isJson(req) {
		encode(resp, req, st)
		return
	}
	print(resp, req, st, hostengine)
}

